// Generated by scripts/build-academy-data.mjs from the Season 1 production sources. Do not edit by hand.
export const ACADEMY_CONTENT = Object.freeze({"locale":"zh-Hant","lessons":[{"ep":1,"title":"一枚比特幣太貴，我就不能買嗎？","goal":"能區分幣的數量與購買金額，知道比特幣可拆分購買。","task":"在模擬頁面把成交金額100換算成幣數量；不建立真實訂單。","answer":"0.002 BTC，計算未扣手續費。","takeaways":["一顆比特幣的價格，不等於入門的門檻。","比特幣可以拆成小數：在 50,000 時花 100，你就持有 0.002 BTC。","每個平台的最低下單金額和手續費都不同，先把這兩項看清楚。"],"quiz":{"q":"一顆比特幣是 50,000 USDT。你花 100 USDT（不計手續費），能得到多少？","options":["什麼都買不到，必須買一整顆","0.002 BTC","0.02 BTC"],"answer":1,"why":"100 ÷ 50,000 = 0.002。你可以只持有一顆比特幣的一小部分。"},"transcript":[{"t":0.25,"who":"sam","text":"一枚這麼貴，我的錢是不是連門票都買不起？"},{"t":9.25,"who":"nexubo","text":"你看到的是一整枚的價格，不是每次必須支付的金額。比特幣是一種數位資產，可以按小數數量持有，通常不用一次買一整枚。"},{"t":25.25,"who":"narrator","text":"只做一道假設題：一枚值50,000單位泰達幣，成交金額是100，忽略費用，就對應0.002枚比特幣。這不是今天的市場報價。"},{"t":45.25,"who":"sam","text":"那價格漲跌時呢？"},{"t":47,"who":"nexubo","text":"你持有的數量可以不變，折合價值卻會漲，也會跌。買得少，只是投入少，不等於沒有風險。"},{"t":62.25,"who":"nexubo","text":"能拆分，不代表所有平台都接受任意小的訂單。還要檢查最小金額和費用。學習階段先用虛擬資金，不需要充值。"},{"t":75.25,"who":"narrator","text":"購買比特幣必須買一整枚嗎？不必。記住：整枚的價格，不是入門的門檻。"},{"t":86.25,"who":"narrator","text":"大多數交易都用USDT標價。可它真的是美元嗎？下一集揭曉。"},{"t":92.55,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":2,"title":"USDT是美元嗎？為什麼買幣常見它？","goal":"理解穩定幣的用途、目標錨定及風險，知道買幣不必先買USDT。","task":"把「美元存款」「USDT」「BTC」放進正確類別。","answer":"USDT屬於加密資產中的穩定幣，不是銀行美元存款。","takeaways":["USDT 是穩定幣，設計上盡量貼近一美元，但它不是銀行存款。","交易所用它來計價和兌換資產，所以賣出後拿到的常常是 USDT。","「穩定」是設計目標：價格可能偏離，贖回也有條件。"],"quiz":{"q":"關於 USDT，哪一句是對的？","options":["它就是你銀行帳戶裡的美元","它是穩定幣，是加密資產的一種","它永遠不會偏離一美元"],"answer":1,"why":"USDT 以追蹤美元為目標，但它是加密資產，有自己的發行方風險和平台風險。"},"transcript":[{"t":0.25,"who":"sam","text":"這個叫泰達幣，所以它就是美元存款？"},{"t":9.25,"who":"nexubo","text":"不是。泰達幣是一種穩定幣，設計目標是儘量貼近一美元，但它不是你銀行帳戶裡的美元，也不是沒有風險的現金。"},{"t":25.25,"who":"narrator","text":"交易裡常用它作為報價和交換的資產。比如你用泰達幣買比特幣，賣出後也可能收到泰達幣，而不是直接收到銀行轉帳。"},{"t":45.25,"who":"nexubo","text":"所謂穩定，是設計目標，不是絕對保證。價格可能偏離，發行與贖回也有條件；持用時仍要了解發行方和平台風險。"},{"t":62.25,"who":"sam","text":"所以買幣必須先買泰達幣？"},{"t":65.23,"who":"nexubo","text":"也不一定。支援哪些法幣和交易對，要看你所在地區與平台提供的服務。"},{"t":75.25,"who":"narrator","text":"這句話錯在哪裡？穩定幣不是保本承諾；理解用途，也要理解它可能不穩定。"},{"t":86.25,"who":"narrator","text":"如果今晚手機摔壞，你的幣也會沒嗎？下一集：幣到底在哪。"},{"t":92.15,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":3,"title":"幣到底在哪：交易所和錢包有什麼不同？","goal":"能區分託管交易帳戶與自託管錢包，理解控制權與恢復責任。","task":"匹配兩個場景：交易所登入帳戶；普通助記詞自託管錢包。","answer":"兩者控制權和恢復機制不同；自託管不等於自動安全。","takeaways":["在交易所帳戶裡，資產和金鑰主要由平台管理。","在自託管錢包裡，憑證由你掌握，找回的責任也在你身上。","選擇之前，先問清楚：誰有權限把資產轉走？"],"quiz":{"q":"你弄丟了一般自託管錢包的助記詞，也沒有其他找回方式，會發生什麼事？","options":["客服可以幫你重設","可能永遠失去存取權","交易所會自動幫你恢復"],"answer":1,"why":"自託管代表金鑰在你手上。沒有助記詞或其他有效方式，誰也無法替你找回。"},"transcript":[{"t":0.25,"who":"sam","text":"手機壞了，幣是不是也一起摔沒了？"},{"t":9.25,"who":"nexubo","text":"不是把硬幣裝進手機。錢包幫你查看鏈上資產，並用金鑰授權操作。能否恢復，取決於你用什麼錢包、保留了哪些恢復方式。"},{"t":32.25,"who":"narrator","text":"交易所託管帳戶主要由平台管理底層資產與金鑰，你用帳戶操作。自託管錢包則由你負責控制憑證；使用方便與責任分配不同。"},{"t":60.25,"who":"sam","text":"兩邊忘記密碼都找客服？"},{"t":63.86,"who":"nexubo","text":"不能這樣想。普通助記詞錢包的恢復憑證丟失，且沒有其他有效恢復方式時，客服無法替你找回。"},{"t":84.25,"who":"nexubo","text":"放在平台有平台風險，自己保管也會因洩漏金鑰或錯誤授權損失。今天只理解區別，不要求你立刻搬走所有資產。"},{"t":103.25,"who":"narrator","text":"誰在控制資產的操作權限？先回答這件事，再決定你需要哪種帳戶或錢包。"},{"t":116.25,"who":"narrator","text":"兩扇門一模一樣，其中一扇是假的。下一集：怎麼認出真門。"},{"t":121.75,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":4,"title":"先認準真門：開戶別盲目","goal":"註冊前先核對官網網域、地區要求，並開通基礎安全設定。","task":"在模擬註冊頁面的網址列中找出不符點。","answer":"官方網域名稱不一致。不要在可疑網站輸入任何資訊。","takeaways":["第一件事：確認平台有服務你實際所在的國家。","只透過確認過的官方入口註冊，使用你自己的電子郵件或手機號碼。","註冊完成後，立刻開啟安全功能並保存好找回方式。"],"quiz":{"q":"註冊之前，最先要確認什麼？","options":["新手獎勵有多大","平台有服務你的國家，而且入口是官方的","平台有多少追蹤者"],"answer":1,"why":"資格和官方入口排在最前面。獎勵永遠不該決定你在哪裡開戶。"},"transcript":[{"t":0.25,"who":"sam","text":"我在網上搜交易所，搜出十個差不多的連結。到底哪個是真的？"},{"t":9.25,"who":"nexubo","text":"別隨便點。註冊前先核對四件事：官網網域、地區要求、可用產品和帳戶安全。"},{"t":32.25,"who":"narrator","text":"確認官方入口後，再用自己的郵箱或手機號註冊，設置獨立密碼，完成頁面要求的驗證。不要購買別人的帳戶，也不要虛構身分和地區。"},{"t":60.25,"who":"nexubo","text":"註冊不是最後一步。把平台支援的安全措施設定好，檢查登入裝置，保存恢復方式。一次性驗證碼也不能發給所謂的客服代辦。"},{"t":84.25,"who":"narrator","text":"我們的網站可以幫助你查資訊，但推廣關係不等於安全擔保。資料未確認時，先不進入開戶流程。"},{"t":103.25,"who":"sam","text":"停止，先確認資格和規則。"},{"t":107.02,"who":"nexubo","text":"對。先認門，再開戶。"},{"t":127.35,"who":"narrator","text":"現在就做：打開兩步驟驗證。然後回來——下一集，有人在聊天裡說能替你代辦認證。"},{"t":134.45,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":5,"title":"KYC怎麼做？證件應該交給誰？","goal":"理解身分認證的一般目的和流程，知道只向核驗後的官方管道提交。","task":"用虛構資訊排列認證步驟；課程禁止上傳真實證件。","answer":"核驗入口→按本地區要求提交真實本人資料→等待並核對結果。","takeaways":["KYC 用來確認你是帳戶本人，也幫助平台符合法規要求。","證件只在官方驗證流程裡提交，絕不在聊天中傳送。","驗證失敗時，先看原因、修正，再用真實身分重試。"],"quiz":{"q":"你的證件應該交給誰？","options":["聊天群組裡熱心的「專員」","只有經過確認的官方驗證流程","課程聊天室，讓其他人幫你看"],"answer":1,"why":"只交給官方流程。NexuAlpha 從不索取你的證件，陌生人也不應該。"},"transcript":[{"t":0.25,"who":"sam","text":"它要我的證件，旁邊這個人說能幫我代辦？"},{"t":9.25,"who":"nexubo","text":"身分認證通常用來核實帳戶本人、滿足合規要求。先確認是官方流程，不要把證件、驗證碼交給聊天群裡的代辦。"},{"t":32.25,"who":"narrator","text":"一般先填真實資訊，再提交支援的有效證件，按提示完成照片或本人驗證。是否需要地址證明、接受什麼證件，都取決於地區和平台。"},{"t":60.25,"who":"nexubo","text":"失敗時先看原因：證件是否過期、畫面是否反光、姓名是否一致。按提示補正，不要換一個虛假的身分去嘗試。"},{"t":84.25,"who":"sam","text":"做完是不是馬上能交易？"},{"t":86.78,"who":"nexubo","text":"不保證。審核結果、可用產品和入金資格都要看官方通知。這個學院也不收集你的真實證件。"},{"t":103.25,"who":"narrator","text":"證件交給誰？只按核驗後的官方流程提交，不交給我們，也不交給陌生人。"},{"t":127.25,"who":"narrator","text":"充值、買幣、劃轉，三個按鈕長得都像。下一集：到底該按哪個。"},{"t":132.85,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":6,"title":"首次入金：錢從哪裡來，又進到哪裡去？","goal":"區分法幣充值、直接買幣、加密充幣和內部劃轉，檢查通道與費用。","task":"匹配三個場景：銀行法幣充值、既有加密充幣、帳戶間內部劃轉。","answer":"不同通道的規則、費用和到帳時間不同；內部劃轉不走區塊鏈。","takeaways":["法幣入金、購買加密貨幣、鏈上充值和內部轉帳是不同的路線。","鏈上充值需要支援的幣種和網路；內部轉帳只在平台內進行。","絕不在平台外付錢給陌生人；先確認餘額會到哪裡。"],"quiz":{"q":"你在同一個平台上，把 USDT 從資金帳戶轉到交易帳戶。這是什麼？","options":["鏈上充值","內部轉帳","法幣入金"],"answer":1,"why":"這只是在你自己的帳戶之間移動餘額，通常不是鏈上轉帳。"},"transcript":[{"t":0.25,"who":"sam","text":"充值、買幣、劃轉，這三個按鈕不都是把錢放進去嗎？"},{"t":9.25,"who":"nexubo","text":"不是，它們調動的資產不同。你是把法定貨幣存進來、把既有加密資產轉進來，還是在自己帳戶間調配餘額？"},{"t":32.25,"who":"narrator","text":"法幣充值通常是給帳戶增加法幣餘額；直接買幣則是付款後獲得加密資產。有的平台支援銀行或信用卡管道，有的不支援，費用和限制也不同。"},{"t":60.25,"who":"nexubo","text":"已有加密資產，可以按支援的幣種和網絡充值。平台內部劃轉是帳戶間調配餘額，通常不是鏈上轉帳。先確認餘額會到哪裡。"},{"t":84.25,"who":"narrator","text":"有的平台還提供用戶間交易，但不是銀行轉帳的同義詞。不要私下脫離平台付款，不使用來路不明或第三方代付資金；沒看懂就先不操作。"},{"t":103.25,"who":"sam","text":"不能，這是不同通道。"},{"t":105.59,"who":"nexubo","text":"對，先看資產，再看路徑，最後核對實際到帳。"},{"t":116.25,"who":"narrator","text":"BTC/USDT中間這道斜線，是要買兩種幣嗎？下一集：第一筆現貨。"},{"t":122.45,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":7,"title":"第一筆現貨：從100到0.002枚","goal":"完成一筆明確金額、數量和費用的模擬現貨買入。","task":"用虛擬1,000餘額買入0.002 BTC，核對剩餘報價餘額899.90及成交記錄。","answer":"成交金額100，費用0.10，總支出100.10；餘899.90。","takeaways":["BTC/USDT 代表以 USDT 計價的比特幣：你付出 USDT，得到比特幣。","看清楚下單框要你填的是金額，還是幣的數量。","買完之後查看成交紀錄：成交狀態、平均價格和手續費。"],"quiz":{"q":"你以 50,000 買入 0.002 BTC，另外以 USDT 收取 0.1% 手續費。總共花了多少？","options":["100","100.10","110"],"answer":1,"why":"幣的部分 100，加上 0.10 的手續費，共 100.10。"},"transcript":[{"t":0.25,"who":"sam","text":"這個斜線，是讓我同時買兩種幣嗎？"},{"t":9.25,"who":"nexubo","text":"不是。這表示用泰達幣來給比特幣報價。買入時，你付出報價資產，獲得比特幣；賣出時方向相反。"},{"t":35.25,"who":"narrator","text":"我們用虛擬帳戶練習。確認是現貨，不是合約；選擇交易對、買入方向，再輸入成交金額。提交前看清它要求填金額，還是幣的數量。"},{"t":67.25,"who":"nexubo","text":"假設成交價是50,000，成交金額100，就買到0.002枚。再假設手續費0.1%、從報價餘額另扣，你總共支出100.10。真實規則以平台為準。"},{"t":95.25,"who":"sam","text":"按了買入就一定有幣了？"},{"t":99.07,"who":"nexubo","text":"還要查成交記錄。未成交、部分成交和全部成交不同；實際均價和費用也要核對。"},{"t":116.25,"who":"narrator","text":"第一筆練習不是猜漲跌，而是把這五項核對清楚。完成後，你也可以選擇暫時不做真實交易。"},{"t":140.95,"who":"narrator","text":"假如漲了你賣出，為什麼銀行卡餘額還是沒動？下一集講。"},{"t":146.85,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":8,"title":"我賣了，為什麼銀行卡還沒收到錢？","goal":"區分賣出資產、獲得穩定幣或法幣餘額，以及實際銀行提現。","task":"完成模擬賣出，並在資產流向圖中標明哪一步才是銀行提現。","answer":"賣出到USDT不等於銀行提現；本例淨交易盈虧9.79。","takeaways":["賣出換成 USDT，得到的是 USDT 餘額，不是銀行裡的錢。","賣出和提領到銀行是兩個分開的步驟。","價格變高不等於你的淨收益：先扣掉每一筆費用。"],"quiz":{"q":"你把比特幣賣成 USDT。現在錢在哪裡？","options":["在你的銀行帳戶裡","以 USDT 餘額留在平台上","已經換成你的當地貨幣"],"answer":1,"why":"你收到的是 USDT。把錢轉到銀行是另一個提領步驟。"},"transcript":[{"t":0.25,"who":"sam","text":"我明明賣了，銀行卡怎麼還沒收到錢？"},{"t":9.25,"who":"nexubo","text":"先看你賣給了哪個交易對。如果賣成泰達幣，得到的是泰達幣餘額，不是銀行到帳。賣出和法幣提現，是兩個步驟。"},{"t":35.25,"who":"narrator","text":"沿用教學例子，0.002枚按55,000賣出，成交金額110；扣假設費用0.11，到帳109.89。"},{"t":67.25,"who":"sam","text":"那我賺了十？"},{"t":68.76,"who":"nexubo","text":"還要扣成本。這裡是9.79，尚未計算法幣兌換、提現等可能的費用。幣價漲跌並不等於最終淨收益。"},{"t":95.25,"who":"narrator","text":"需要轉回銀行時，先查你所在地區是否支援，再按官方路徑兌換或提現到符合要求的本人帳戶。核對姓名、到帳金額、費用和預計處理條件。"},{"t":116.25,"who":"sam","text":"不是。"},{"t":116.98,"who":"nexubo","text":"保留交易和提現記錄；不確定資金性質，就不要根據一個「成功」提示作判斷。"},{"t":131.25,"who":"narrator","text":"便宜一點的網絡，點錯一下，幣就可能找不回。下一集：轉帳前一個也別猜。"},{"t":137.95,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":9,"title":"轉帳之前，這幾項一個也別猜","goal":"會核對幣種、網絡、地址、備註及到帳條件，並先做小額測試。","task":"在故意有錯的模擬提幣表裡糾正網絡不匹配和缺失備註；再做虛擬小額測試。","answer":"所有關鍵條件匹配才可提交；沒有「自動改成正確網絡」的預設保護。","takeaways":["轉出前，先確認收款方支援的幣種和網路。","從收款頁面複製地址，完整核對一遍，並填上需要的 memo 或 tag。","先小額測試一次，確認到帳。"],"quiz":{"q":"收款頁面要求填寫 memo。你該怎麼做？","options":["略過，有地址就夠了","完全照顯示的內容填寫 memo","沿用以前轉帳的 memo"],"answer":1,"why":"如果需要 memo 或 tag，沒填的話這筆轉帳可能無法到帳。"},"transcript":[{"t":0.25,"who":"sam","text":"這個網絡更便宜，隨便換它不就好了？"},{"t":9.25,"who":"nexubo","text":"先確認收款方支援哪種資產和網絡，再選擇費用。兩端不匹配，不能因為便宜就發送。同叫泰達幣，也可能在不同網絡上。"},{"t":39.25,"who":"narrator","text":"你可以暫時把網絡想成路線，把地址想成目的地，但地址看起來一樣，也不代表網絡相容。必須查看接收平台對這條鏈和這項資產的支援。"},{"t":75.25,"who":"nexubo","text":"從收款頁面複製地址，再核對完整內容。若要求備註或標籤，也要填寫。確認最低充值、提幣費用和到帳金額；不要只靠地址前後幾個字元判斷。"},{"t":106.25,"who":"narrator","text":"先做一筆滿足最低條件的小額測試，並確認接收方實際入帳。後續大額仍要重新核對，不能盲目複用歷史記錄。自託管轉帳還要準備相應網絡手續費。"},{"t":130.25,"who":"sam","text":"不能。"},{"t":131.16,"who":"nexubo","text":"轉帳前多核對一次，比轉錯後找人補救更重要。"},{"t":146.25,"who":"narrator","text":"顯示成功卻沒到帳？先別再轉。下一集：該查哪裡。"},{"t":151.65,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":10,"title":"顯示成功卻沒到帳，該查哪裡？","goal":"能區分發送方處理、鏈上確認和平台入帳，知道有限補救路徑。","task":"將三個故障場景匹配到發送方、鏈上狀態和接收方。","answer":"定位狀態再找相應官方管道；未知原因不重複付款。","takeaways":["已提交、已上鏈、已到帳，是三個不同的站點。","拿交易雜湊到對應網路的區塊瀏覽器上查詢。","只把紀錄提供給官方客服，絕不交出助記詞、私鑰或驗證碼。"],"quiz":{"q":"你的轉帳顯示「已送出」，但還沒到帳。第一步該做什麼？","options":["再送一次同樣的金額","用紀錄和交易雜湊找出卡在哪一站","付錢給聲稱能幫你追回的人"],"answer":1,"why":"先找出卡在哪一站，再聯絡對應的官方管道。不要一直重送。"},"transcript":[{"t":0.25,"who":"sam","text":"沒到帳，我再轉幾筆試試？"},{"t":9.25,"who":"nexubo","text":"先別重複轉。已提交、已上鏈、已入帳不是一回事。先確認卡在哪一站，再決定該聯繫誰。"},{"t":32.25,"who":"narrator","text":"保存發送記錄。若有交易哈希，在對應網絡的正規區塊瀏覽器查看狀態、目標地址和數量；不要把另一條鏈的查詢結果混進來。"},{"t":60.25,"who":"nexubo","text":"接收平台可能還需要確認數或內部審核。若幣種、網絡、地址或備註填錯，先停止繼續轉帳，提交事實資料給官方客服。"},{"t":84.25,"who":"narrator","text":"通常不能像撤銷普通操作一樣撤回已完成的鏈上轉帳。是否能找回，要看技術和平台條件，不能保證；別相信付錢就必定找回。"},{"t":103.25,"who":"sam","text":"提供必要交易記錄，不提供助記詞、私鑰和驗證碼。"},{"t":107.92,"who":"nexubo","text":"對，先定位，不盲目補轉。"},{"t":116.25,"who":"narrator","text":"「我是客服，把恢復詞發給我。」下一集：騙子到底要什麼。"},{"t":122.45,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":11,"title":"別人說能幫你賺錢，先看他要什麼","goal":"識別祕密憑證索取、私下付款、異常授權和保本承諾。","task":"識別四段虛構聊天的危險請求，選擇停止和官方核驗路徑。","answer":"任何人索取私鑰、恢復詞、驗證碼或不明授權，都不應照做。","takeaways":["助記詞和私鑰是控制權的鑰匙，不是客服用的代碼。","保證獲利和催你付款，都是危險信號。","看不懂的簽名或授權，絕不要確認。"],"quiz":{"q":"為了收款，哪一項可以安全地分享出去？","options":["你的公開地址","你的助記詞","一次性驗證碼"],"answer":0,"why":"公開地址本來就是用來收款的。機密資訊和驗證碼會把控制權交出去。"},"transcript":[{"t":0.25,"who":"sam","text":"他說自己是客服，要幫我升級錢包。"},{"t":9.25,"who":"nexubo","text":"普通助記詞錢包的恢復詞是控制憑證，不是客服驗證碼。私鑰也一樣。不要發給任何人，學院問答助手同樣不該索取。"},{"t":32.25,"who":"narrator","text":"還有兩類危險信號：保證收益、催促付款。高收益截圖不能證明真實，也不說明你能復現。有人催你越過正常核對步驟，就先停下來。"},{"t":60.25,"who":"nexubo","text":"連接錢包、簽署消息和授權資產，不是同一件事。看不懂簽名或授權，就不確認；不要以為沒有輸入密碼就一定沒有風險。"},{"t":84.25,"who":"narrator","text":"懷疑洩漏時，停止繼續操作，使用官方安全管道處理；根據洩漏內容採取針對措施，不要在騙子指揮下下載遠端控制軟體。"},{"t":103.25,"who":"sam","text":"能公開接收資訊，不等於能交出控制憑證。"},{"t":106.72,"who":"nexubo","text":"不交祕密、不亂授權、不被催著付款。"},{"t":116.25,"who":"narrator","text":"看完十一集，是不是該充值了？第1季結課，答案可能出乎你意料。"},{"t":123.15,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":12,"title":"第1季結課：你能做，也可以選擇不做","goal":"完成綜合模擬、理解不交易也是正當選擇，並了解進階學習路徑。","task":"在模擬頁面完成結課三問。","answer":"賣出到USDT不等於銀行提現；鏈上確認不等於平台入帳；不交出控制憑證，存疑不轉帳。","takeaways":["目標是正確的流程：入口與資格、現貨、金額與手續費，最後看紀錄。","停下一筆不清楚的轉帳，也是正確答案。","你的證書是學習紀錄，不是投資的許可證。"],"quiz":{"q":"練習轉帳時，畫面顯示的網路不對。正確的做法是什麼？","options":["照樣送出，碰碰運氣","停下來，不要送出","改成更大的金額"],"answer":1,"why":"當網路、費用或身分不清楚時，停下來比完成任務更重要。"},"transcript":[{"t":0.25,"who":"sam","text":"我全部學完了，是不是就代表能真金白銀去實操了？"},{"t":9.25,"who":"nexubo","text":"先別急。今天做一次完整的全流程模擬。核對真門、現貨、金額與費用，再看成交記錄。有疑問就不交易。"},{"t":39.25,"who":"narrator","text":"做對是指看清風險、平靜核對。評分不代表未來盈利保證。答錯任何一題，就回到對應章節重新看。"},{"t":75.25,"who":"sam","text":"這條轉帳資訊有問題，我不轉。"},{"t":78.5,"who":"nexubo","text":"這也是正確答案。遇到不確定的網絡、費用或身分資訊，停下比強行完成任務更重要。"},{"t":106.25,"who":"narrator","text":"最後複述三個判斷：資產去了哪裡，錢實際扣了多少，以及誰能控制你的帳戶。說不清楚的部分，就回到對應課程再練一次。"},{"t":130.25,"who":"nexubo","text":"你獲得的是學習記錄，不是投資資格。繼續學習可以，暫時不交易也可以。先看懂，再動手。"},{"t":157.55,"who":"narrator","text":"第2季：你看到的價格，不一定是你付的價格。下一季揭曉。"},{"t":163.05,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":13,"title":"螢幕上的價格，為什麼不是我的成交價？","goal":"理解訂單簿、買賣價差、成交深度、手續費與滑點。","task":"在兩檔虛擬賣單中撮合0.002 BTC，計算加權平均價。","answer":"總額100.10，均價50,050；這是成交金額，尚未另扣教學手續費。若另收0.1%報價資產手續費：費用0.1001，總支出100.2001（不能先四捨五入再計算）。","takeaways":["最新價是最近一筆成交，不代表任何數量都能用這個價格成交。","較大的訂單可能會分散在訂單簿的好幾檔價格成交。","滑價和交易手續費是兩筆不同的成本：要看清楚帳單。"],"quiz":{"q":"你的 0.002 BTC 一半在 50,000 成交，另一半在 50,100 成交。平均價格是多少？","options":["50,000","50,050","50,100"],"answer":1,"why":"兩個相等的一半，平均是 50,050。手續費是另外加上的成本。"},"transcript":[{"t":0.25,"who":"sam","text":"剛才明明是這個價，怎麼我的帳單變了？"},{"t":9.25,"who":"nexubo","text":"螢幕上的最新價，是最近一筆成交的記錄，不是給你無限數量的報價。現在有人願意買多少、賣多少，要看買賣盤。"},{"t":32.25,"who":"narrator","text":"假設你買0.002枚，第一檔只有一半，另一半只能在更高價位成交。兩筆合起來，平均是50,050，而不是50,000。"},{"t":60.25,"who":"nexubo","text":"滑點是預期價和實際成交價的差異，不一定都是壞方向。交易費則是另一項成本；不要把它們混在一個「免費」口號裡。"},{"t":84.25,"who":"narrator","text":"訂單更大、可成交深度更少或行情變化更快時，成交結果更可能偏離預期。下單前看金額和深度，成交後看實際均價。"},{"t":103.25,"who":"sam","text":"不能。"},{"t":104.04,"who":"nexubo","text":"看到帳單才算清楚成交，不只盯著最大的那個數字。"},{"t":126.75,"who":"narrator","text":"下了買單卻遲遲不成交，系統壞了嗎？下一集：市價、限價和撤單。"},{"t":132.45,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":14,"title":"市價、限價、撤單，分別解決什麼問題？","goal":"會根據成交優先或價格邊界選擇訂單，並理解未成交和部分成交。","task":"放置虛擬限價單、觀察部分成交，再撤銷剩餘數量。","answer":"價格條件合適也受可成交數量等因素影響；已成交部分不能被撤單逆轉。","takeaways":["市價單用當下可成交的價格快速成交；最終價格可能會變動。","限價單能鎖住你的價格上限，但不一定會成交。","撤單只影響未成交的部分；已成交的部分不會改變。"],"quiz":{"q":"你的限價單成交了一半，接著你撤單。會發生什麼事？","options":["全部都被撤回","只有未成交的那一半被取消","已成交的那一半變成市價單"],"answer":1,"why":"撤單無法倒轉已經成交的部分，只會停止剩下的數量。"},"transcript":[{"t":0.25,"who":"sam","text":"我按了買入，為什麼一直不成效？"},{"t":9.25,"who":"nexubo","text":"市價單傾向於儘快按當前可用報價成交，但最終價格可能變化。限價單規定買入不超過、賣出不低於某個價格，不保證成交。"},{"t":32.25,"who":"narrator","text":"想低於當前價格買，就可能需要等待。反過來，限價單若已經滿足對手盤條件，也可能立即成交，不是每張限價單都只能排隊。"},{"t":60.25,"who":"sam","text":"那撤單是不是把剛才買的也撤掉？"},{"t":62.82,"who":"nexubo","text":"不是。撤單只處理尚未成交的部分；已經成交的資產變化不會被倒放。"},{"t":84.25,"who":"narrator","text":"看清狀態再操作。是否屬於掛單方或吃單方，要看實際成交方式；並不是選擇限價，就必定得到某一種費率。"},{"t":103.25,"who":"sam","text":"不會。"},{"t":104.12,"who":"nexubo","text":"選訂單是在選擇執行方式，不是在許願。"},{"t":116.25,"who":"narrator","text":"綠色蠟燭，是不是代表下一根也會漲？下一集。"},{"t":121.05,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":15,"title":"一根K線，到底告訴你哪四件事？","goal":"讀出開、高、低、收與時間週期，不把顏色或單根形態當預測。","task":"在虛擬K線上點擊開、高、低、收，並確認圖表週期。","answer":"50,000／51,000／49,000／50,500；週期五分鐘。","takeaways":["一根 K 線呈現一個時段的四個價格：開盤、最高、最低和收盤。","先看時間週期，再看形狀：五分鐘不等於一天。","不同 App 的顏色不同，而且一根 K 線是紀錄，不是預測。"],"quiz":{"q":"一根五分鐘 K 線開在 50,000，漲到 51,000，跌到 49,000，收在 50,500。最高價是多少？","options":["50,500","51,000","49,000"],"answer":1,"why":"上影線的頂端就是這個時段的最高價：51,000。"},"transcript":[{"t":0.25,"who":"sam","text":"綠色，是不是表示下一秒還會漲？"},{"t":9.25,"who":"nexubo","text":"一根K線記錄一個時間段的四個價格：開盤、最高、最低、收盤。這裡是虛構的五分鐘行情，不是未來五分鐘的保證。"},{"t":32.25,"who":"narrator","text":"實體幫助你看開盤與收盤的差，影線標出期間到過的高低點。還沒結束的這根線，會隨著新成交繼續改變。"},{"t":60.25,"who":"sam","text":"為什麼切換週期，圖看起來就不一樣？"},{"t":63.75,"who":"nexubo","text":"每根線代表的時間長度變了。先讀週期，再談形狀，不能把五分鐘當成一天。"},{"t":84.25,"who":"narrator","text":"不同應用可能使用不同漲跌顏色，所以要看圖例和數字。歷史走勢可以提供資訊，但單根K線不能保證下一步漲跌。"},{"t":103.25,"who":"sam","text":"最高51,000，收盤50,500。"},{"t":108.91,"who":"nexubo","text":"先讀記錄，別把記錄當預言。"},{"t":116.25,"who":"narrator","text":"「我有1,000，只想虧20，那就全買進去？」下一集：先想能虧多少。"},{"t":122.35,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":16,"title":"先想能虧多少，再決定買多少","goal":"理解帳戶資金、倉位金額和計畫風險不是同一個數字。","task":"根據給定入場、止損距離和教學風險預算，算出虛擬倉位。","answer":"400 USDT名義現貨金額；0.008 BTC；費用和執行偏差需另計。","takeaways":["帳戶餘額、倉位大小和計畫承擔的風險，是三個不同的數字。","先決定出場點，再決定倉位大小。","停損距離 5%、風險預算 20，倉位大約是 400。"],"quiz":{"q":"進場 50,000，計畫出場 47,500，你能接受虧損 20。倉位大約多大？","options":["20","400","4,000"],"answer":1,"why":"出場點相距 5%，而 400 的 5% 就是 20。成本另外計算。"},"transcript":[{"t":0.25,"who":"sam","text":"我有1,000，只想虧20，那就先全買進去？"},{"t":9.25,"who":"nexubo","text":"帳戶裡有多少、這一筆買多少、計畫最多承擔多少損失，是三件不同的事。先有退出條件，才能估算倉位。"},{"t":35.25,"who":"narrator","text":"只看一道練習題：入場50,000，計畫在47,500退出，差5%。假設你計畫承擔20的價格損失，忽略成本時，倉位約為400。"},{"t":67.25,"who":"sam","text":"原來「最多虧20」，不等於「只買20」？"},{"t":70.55,"who":"nexubo","text":"對。這裡400的倉位跌5%，才對應20；這只是教學參數。"},{"t":95.25,"who":"narrator","text":"真實行情會有滑點、跳空、費用或執行失敗，所以計畫風險不等於保證最多虧這麼多。不要借錢來完成課程，也不要把生活必需資金當練習。"},{"t":116.25,"who":"sam","text":"二十。"},{"t":116.98,"who":"nexubo","text":"先算最壞能接受什麼，再看你是否需要這筆交易。"},{"t":131.25,"who":"narrator","text":"設好了止損，就一定只虧這麼多嗎？下一集：止損的真相。"},{"t":137.75,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":17,"title":"止盈止損，是計畫，不是保險","goal":"理解觸發與成交的區別，能識別止損市價和止損限價的不同風險。","task":"對比同一段急跌中止損市價和止損限價的模擬結果。","answer":"前者可能滑點，後者可能不成交；二者都不是保本保險。","takeaways":["停損是在執行你的出場計畫，不是保險。","停損市價單出場快，但在行情急動時可能出現滑價。","停損限價單能鎖住價格，但可能完全無法成交。"],"quiz":{"q":"在急跌時，停損限價單可能會怎樣？","options":["一定會在觸發價成交","如果價格一口氣跌過去，可能無法成交","變成一份保險"],"answer":1,"why":"限價保護的是你的價格，所以行情變動太快時，訂單可能一直無法成交。"},"transcript":[{"t":0.25,"who":"sam","text":"止損已經設好，所以一定只虧我填的金額？"},{"t":9.25,"who":"nexubo","text":"止損是條件達到時執行退出計畫，不是保險。觸發了條件，不等於一定按那個價格成交，也不保證損失剛好停在那裡。"},{"t":32.25,"who":"narrator","text":"觸發後按市價執行，重視儘快離場，但實際價格可能有滑點。行情很快或深度不足時，差異可能更大。"},{"t":60.25,"who":"nexubo","text":"觸發後掛限價，能限制接受的成交價格，卻可能因為價格快速穿過而賣不掉。兩種方式不是誰永遠更好，而是不同取捨。"},{"t":84.25,"who":"narrator","text":"設置後檢查方向、數量和訂單狀態。合約還要核對用哪種價格觸發，避免把止損線放在可能先被強平的位置。"},{"t":103.25,"who":"sam","text":"不保證。"},{"t":104.72,"who":"nexubo","text":"明白限制，才能把止損當成有效計畫，而不是護身符。"},{"t":116.25,"who":"narrator","text":"都寫著BTC，其中一個卻可能不給你任何比特幣。下一集：現貨和合約。"},{"t":123.15,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":18,"title":"現貨和合約，買到的不是同一件事","goal":"區分持有資產與持有價格合約，理解做多、做空的方向。","task":"將現貨資產餘額與合約持倉欄位分別匹配到正確頁面。","answer":"合約倉位不等同於可提取的基礎幣資產；課程不要求真實開戶。","takeaways":["現貨是把一種資產換成另一種；永續合約是一個合約倉位。","做多在價格上漲時獲利，做空在價格下跌時獲利；方向錯了就虧損。","合約是另一種風險結構，不是你必須升到的等級。"],"quiz":{"q":"合約倉位會給你可以提領的比特幣嗎？","options":["會，跟現貨一樣","不會，它是結算盈虧的合約","只有開 10x 槓桿才會"],"answer":1,"why":"線性永續合約在合約內結算盈虧，不是可以提領的幣餘額。"},"transcript":[{"t":0.25,"who":"sam","text":"都寫著比特幣，不就是同一種買賣嗎？"},{"t":9.25,"who":"nexubo","text":"沒有借貸的普通現貨，是用一種資產換另一種資產。這裡講的線性永續合約，則是持有按價格變化結算盈虧的合約倉位，不等於買到可提取的比特幣。"},{"t":32.25,"who":"narrator","text":"做多通常希望價格上漲，做空通常希望價格下跌。判斷錯了方向，兩邊都會虧。可以做空，不代表更容易賺錢。"},{"t":60.25,"who":"sam","text":"我應該從現貨升級到合約嗎？"},{"t":62.38,"who":"nexubo","text":"不用。合約是另一種風險結構，不是學習必須達到的等級；知道它是什麼，也可以選擇不用。"},{"t":84.25,"who":"narrator","text":"不借貸的普通現貨沒有合約那種保證金不足強平，但資產仍可能大幅貶值。不能因為沒有強平，就說它保本。"},{"t":103.25,"who":"sam","text":"不是。"},{"t":103.9,"who":"nexubo","text":"先分清交易對象，再研究槓桿。"},{"t":116.25,"who":"narrator","text":"開10倍，平台會送你900嗎？下一集。"},{"t":121.25,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":19,"title":"10倍槓桿，是錢變多，還是風險變大？","goal":"分清保證金、名義倉位和收益率，理解固定倉位下槓桿設置的效果。","task":"分別選擇固定保證金和固定倉位模式，觀察價格變動後的金額盈虧。","answer":"固定保證金提高槓桿會擴大名義倉位；固定倉位則不自動擴大金額盈虧。","takeaways":["用 100 保證金控制 1,000 的倉位，就是 10x 槓桿。","價格變動作用在整個倉位上，結果由你的保證金承擔。","倉位大小不變時，調整槓桿改變的是保證金，不是盈虧。"],"quiz":{"q":"一個 1,000 的倉位朝不利方向變動 1%（不計手續費）。你大約虧多少？","options":["1","10","100"],"answer":1,"why":"1,000 倉位的 1% 大約是 10，從你的保證金中扣除。"},"transcript":[{"t":0.25,"who":"sam","text":"開十倍，平台是不是送我900？"},{"t":9.25,"who":"nexubo","text":"不是送現金。簡化來說，100保證金控制1,000名義倉位，是10倍槓桿。價格變化作用在倉位上，你的保證金承擔對應盈虧。"},{"t":35.25,"who":"narrator","text":"暫不計費用，價格反向1%，1,000倉位大約虧10，2,000倉位大約虧20。百分比看起來很小，對小額保證金卻可能很明顯。"},{"t":67.25,"who":"nexubo","text":"還有一個容易弄錯的地方：如果倉位大小沒變，只調整槓桿設置，同樣價格變化的金額盈虧不會憑空翻倍；主要變化在保證金需求和風險緩衝。"},{"t":95.25,"who":"narrator","text":"實際強平還涉及維持保證金、標記價格與費用，不能說10倍就一定恰好跌10%才爆倉。不要靠這個近似值設置真實交易。"},{"t":116.25,"who":"sam","text":"不會。"},{"t":117.06,"who":"nexubo","text":"放大的是倉位對本金的影響，不是你的判斷能力。"},{"t":131.25,"who":"narrator","text":"保證金還沒歸零，為什麼就可能出局？下一集：那條看不見的線。"},{"t":137.05,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":20,"title":"保證金為什麼還沒歸零，就可能出局？","goal":"區分初始保證金、維持保證金、權益與可用餘額。","task":"給定初始100、浮虧20、暫不計費，填寫簡化權益80；識別變動欄位。","answer":"權益80；維持要求需另按產品規則計算，不能固定認為等於初始保證金。","takeaways":["初始保證金用來開倉；維持保證金用來讓倉位保持開著。","權益是保證金加減未實現盈虧：100 虧 20，剩下 80。","在你的保證金歸零之前，風控系統就可能介入。"],"quiz":{"q":"初始保證金是 100，倉位虧損 20（不計手續費）。簡化後的權益是多少？","options":["100","80","120"],"answer":1,"why":"100 減去 20 的虧損剩下 80；如果價格繼續朝不利方向走，緩衝會越來越小。"},"transcript":[{"t":0.25,"who":"sam","text":"還有餘額，怎麼就不讓我繼續等？"},{"t":9.25,"who":"nexubo","text":"開倉時需要初始保證金；持倉期間，還必須滿足維持保證金要求。初始放了多少，不等於之後一直有多少風險緩衝。"},{"t":35.25,"who":"narrator","text":"假設初始保證金是100，倉位浮虧20，忽略其他項目，相關權益就只剩80。價格繼續不利變化，可用緩衝也會繼續縮小。"},{"t":67.25,"who":"nexubo","text":"當權益接近平台要求的維持水平，風險系統就可能介入；不一定等到全部歸零。具體看哪種帳戶、保證金模式和產品規則。"},{"t":95.25,"who":"sam","text":"那我一直補錢就安全了？"},{"t":99.06,"who":"nexubo","text":"補錢不改變價格方向，也不保證不會被強平。它可能把更多資金帶入同一筆風險。"},{"t":116.25,"who":"sam","text":"不是，一個關乎開倉條件，一個關乎持倉維持要求。"},{"t":121.2,"who":"nexubo","text":"先看權益，再看它離警戒線多遠。"},{"t":131.25,"who":"narrator","text":"把100裝進小盒子，另外900就永遠安全嗎？下一集：逐倉。"},{"t":137.95,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":21,"title":"逐倉：把這筆交易裝進獨立小盒子","goal":"理解單倉保證金隔離及追加保證金可能擴大風險資金。","task":"在模擬設置中找出自動追加開關，並解釋它為何改變參與承擔風險的資金。","answer":"自動或手動追加會增加投入的保證金；不能無條件承諾只損失初始金額。","takeaways":["逐倉保證金讓單一倉位擁有自己的保證金。","你分配的保證金仍然可能全部虧掉；逐倉不是停損。","自動追加或手動追加，都是把更多的錢押在同一個風險上。"],"quiz":{"q":"你替一個逐倉倉位開啟自動追加保證金。會有什麼改變？","options":["沒有改變，虧損仍限於最初的 100","更多餘額可能流入這個倉位","這個倉位變成零風險"],"answer":1,"why":"自動追加會把可用餘額移入倉位，所以有更多的錢在承擔風險。"},"transcript":[{"t":0.25,"who":"sam","text":"放100做逐倉，另外900就永遠碰不到了？"},{"t":9.25,"who":"nexubo","text":"逐倉的核心，是給倉位單獨分配保證金。在不追加、不啟用自動追加等簡化條件下，這個倉位的強平風險主要由分配的保證金承擔。"},{"t":32.25,"who":"narrator","text":"所以它便於區分不同倉位的保證金範圍。但這100本身仍可能損失，逐倉不是讓虧損消失，也不是止損訂單。"},{"t":60.25,"who":"nexubo","text":"注意這個開關：有的平台提供自動追加保證金。打開後，可用餘額可能繼續流入倉位。手動追加也一樣，會讓更多資金參與承擔風險。"},{"t":84.25,"who":"narrator","text":"別只看\"逐倉\"兩個字就假定最大損失永遠等於最初那100。具體還要核對追加設置、費用和產品規則。"},{"t":103.25,"who":"sam","text":"不能。"},{"t":103.99,"who":"nexubo","text":"逐倉看隔離範圍，也要看有沒有額外接進來的管道。"},{"t":116.25,"who":"narrator","text":"一個倉位漏水，另一個也開始下沉。下一集：全倉。"},{"t":121.15,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":22,"title":"全倉保證金：為什麼一處虧損會波及你的其他倉位","goal":"理解單一保證金池的共享風險，不把全倉保證金誤認為覆蓋所有個人資產。","task":"讓一個虛擬倉位虧損，觀察同池風險變化，並圈出不在該保證金池內的資產。","answer":"風險可擴展到同一保證金池；不自動覆蓋所有個人資產。","takeaways":["全倉保證金讓多個倉位共用一個保證金池。","一個虧損的倉位，可能吃掉其他倉位依賴的緩衝。","它不會動到你的銀行卡或個人錢包。"],"quiz":{"q":"全倉保證金一定比較安全嗎？","options":["是，它永遠不會被強制平倉","不一定，要看共用的保證金池和規則","是，它會動用你所有的銀行卡"],"answer":1,"why":"多出的保證金可能延後風險處理，但也讓你更多的錢暴露在風險中。"},"transcript":[{"t":0.25,"who":"sam","text":"虧損的是左邊那個，為什麼右邊的也危險了？"},{"t":9.25,"who":"nexubo","text":"全倉保證金在規則允許的範圍內讓多個倉位共享保證金。比如這裡一個保證金池有 1,000，多個倉位都可能依賴它，而不只是各自最初分配的資金。"},{"t":39.25,"who":"narrator","text":"一個虧損倉位會消耗其他倉位依賴的安全緩衝。盈虧、未成交掛單佔用的保證金以及抵押品的價值變動，都會影響同一帳戶的整體風險。"},{"t":75.25,"who":"sam","text":"那全倉是不是更不容易爆倉，所以更安全？"},{"t":79.67,"who":"nexubo","text":"更多資金確實能延緩單個倉位觸發風控的時間。但這也意味著把更多的錢押上去承擔虧損。"},{"t":106.25,"who":"narrator","text":"全倉保證金並不代表平台能自動劃扣你的銀行卡或個人錢包。哪些帳戶和抵押品算入取決於產品規則。複雜的抵押品還可能伴隨折算率（haircut）和其自身的價格風險。"},{"t":130.25,"who":"sam","text":"不一定。這取決於共享池和帳戶規則。"},{"t":135.19,"who":"nexubo","text":"要看整個保證金池，而不只是單個倉位的格子。"},{"t":146.25,"who":"narrator","text":"你盯著的價格還沒碰到那條線，警報卻響了。下一集：是誰按下了強平按鈕。"},{"t":152.55,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":23,"title":"爆倉強平：是誰按下了強制平倉按鈕？","goal":"理解強平觸發條件、標記價格與維持保證金要求，不把槓桿倍數倒數當作精確公式。","task":"播放同一段先跌後漲的虛擬行情，分別觀察普通現貨和簡化逐倉合約。","answer":"路徑風險重要；合約中途強平後不會因後續反彈自動恢復倉位。","takeaways":["許多永續合約依據標記價格和保證金規則判斷強制平倉，而不是最新成交價。","接近維持保證金要求時，系統可能會減倉或平倉。","倉位一旦被平掉，價格反彈時也不會回來。"],"quiz":{"q":"一個槓桿倉位被強制平倉，之後價格又漲回來。會怎樣？","options":["倉位會自己回來","倉位仍然是平掉的；過程中的路徑才是關鍵","交易所會退還虧損"],"answer":1,"why":"一旦被強制平倉，倉位就沒了。之後的反彈只對仍然持倉的人有幫助。"},"transcript":[{"t":0.25,"who":"sam","text":"我盯著的價格明明還沒到，警報怎麼就響了？"},{"t":9.25,"who":"nexubo","text":"最新成交價並不一定是判定強平的價格。許多永續合約使用標記價格和保證金規則來評估風險。請核實你的平台具體採用哪種規則。"},{"t":35.25,"who":"narrator","text":"當行情逆向運動時，虧損會侵蝕淨值。接近維持保證金時，系統可能會撤單、減倉或強制平倉，未必會等待你的確認。"},{"t":67.25,"who":"nexubo","text":"爆倉強平通常指的是這種強制平倉的風控事件，而不是你的手機按鈕壞了。實際觸發取決於手續費、維持保證金、保證金模式等，10倍槓桿並不等於剛好跌 10%。"},{"t":95.25,"who":"sam","text":"後來明明漲回來了，我不能等它回來嗎？"},{"t":99.46,"who":"nexubo","text":"倉位被強平後不會自動恢復。「先跌後漲」對於槓桿倉位和一直拿著的普通現貨來說，結局可能完全不同。"},{"t":116.25,"who":"sam","text":"不保證。"},{"t":117.73,"who":"nexubo","text":"重要的不只是終點，而是你能不能在波動的路徑中活下來。"},{"t":131.25,"who":"narrator","text":"價格沒怎麼變，你也沒平倉，餘額卻縮水了。下一集，收官終章。"},{"t":137.35,"who":"narrator","text":"先看懂，再動手。"}]},{"ep":24,"title":"價格沒變，餘額縮水？帶著成本算計通關最後一關","goal":"搞清資金費率的方向與計算基數，完整核對合約風險清單，並能夠主動選擇不交易。","task":"計算單期費用 0.10，並完成虛擬合約訂單核對；不得調用真實下單介面。","answer":"正費率多付空收；本例費用 0.10；風險關鍵題全部答對或明確選擇不交易。","takeaways":["資金費用在多方和空方之間支付，不是付給交易所的固定費用。","它依倉位價值計算：1,000 乘以 0.01% 等於 0.10。","選擇不交易，也是及格的答案。"],"quiz":{"q":"資金費率為正時，通常由誰支付？","options":["空方付給多方","多方付給空方","所有人都付給交易所"],"answer":1,"why":"費率為正時，通常由多方付給空方；費率為負時則相反。"},"transcript":[{"t":0.25,"who":"sam","text":"價格明明沒怎麼動，我也沒平倉，餘額怎麼少了？"},{"t":9.25,"who":"nexubo","text":"除了交易手續費，永續合約通常還有資金費用機制。當費率為正時，通常多頭向空頭付費；為負時則反過來。這不是每個人都要向交易所支付的固定利息。"},{"t":42.25,"who":"narrator","text":"假設結算時倉位價值為 1,000，費率為 0.01%，這筆費用就是 0.10。它是按整個倉位價值計算的，而不是你最初的 100 保證金。"},{"t":83.25,"who":"nexubo","text":"結算間隔和費率會隨交易對、平台和市場行情改變。不要死記成「任何合約每八小時收一次」。也切勿把收取資金費用當作無風險收益。"},{"t":117.25,"who":"narrator","text":"最後一關僅供練習。先講清楚你在交易什麼、哪個方向，再核對模式、規模、保證金、自動追加、離場計畫和成本。有任何一項不明白就先停下來，絕不要靠猜按鈕去操作。"},{"t":144.25,"who":"sam","text":"我知道怎麼操作，也清楚這種風險不適合我。所以我選擇不交易。"},{"t":149.09,"who":"nexubo","text":"這同樣是及格的結果。學完課程不代表能賺錢。先看懂，再動手。"},{"t":172.75,"who":"narrator","text":"你已經完成了兩季全部課程。挑出你覺得最難的那一集，在實際交易前再看一遍。"},{"t":178.65,"who":"narrator","text":"先看懂，再動手。"}]}]});
